import {validZone,localToEpoch} from './timezones.mjs';
export const defaults={lang:'zh',zone:'Africa/Porto-Novo',rainYellow:1,rainRed:5,probYellow:30,probRed:60,wet24:30,asphalt:15,concrete:25,wind:10,cape:1000,model:'google_weathernext2_ensemble',commercial:false,weatherSource:'openmeteo',scheduled:true,sites:[],route:[]};
export const valid=n=>typeof n==='number'&&Number.isFinite(n);
export const max=a=>a.filter(valid).length?Math.max(...a.filter(valid)):null;
export function q(a,p){a=a.filter(valid).sort((a,b)=>a-b);if(!a.length)return null;let x=(a.length-1)*p,l=Math.floor(x);return a[l]+(a[Math.ceil(x)]-a[l])*(x-l)}
export const worst=a=>a.includes(2)?2:a.includes(-1)?-1:a.includes(1)?1:a.length?0:-1;
export function distance(a,b){let r=Math.PI/180,dlat=(b[0]-a[0])*r,dlon=(b[1]-a[1])*r;return 6371008.8*2*Math.asin(Math.min(1,Math.sqrt(Math.sin(dlat/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin(dlon/2)**2)))}
export function interpolate(a,b,f){const r=Math.PI/180,d=distance(a,b)/6371008.8;if(d<1e-12)return a;let A=Math.sin((1-f)*d)/Math.sin(d),B=Math.sin(f*d)/Math.sin(d),x=A*Math.cos(a[0]*r)*Math.cos(a[1]*r)+B*Math.cos(b[0]*r)*Math.cos(b[1]*r),y=A*Math.cos(a[0]*r)*Math.sin(a[1]*r)+B*Math.cos(b[0]*r)*Math.sin(b[1]*r),z=A*Math.sin(a[0]*r)+B*Math.sin(b[0]*r);return [Math.atan2(z,Math.hypot(x,y))/r,Math.atan2(y,x)/r]}
export const geo=a=>a.length===2&&a.every(valid)&&Math.abs(a[0])<=90&&Math.abs(a[1])<=180;
export const pk=m=>{m=Math.round(m);return `K${Math.floor(m/1000)}+${String(m%1000).padStart(3,'0')}`};
export function sample(path,origin=0){if(path.length<2||!path.every(geo)||!valid(origin)||origin<0)throw Error('Invalid route');let segments=path.slice(1).map((b,i)=>distance(path[i],b)),length=segments.reduce((a,b)=>a+b,0);if(length<1||length>450000)throw Error('Route: 1 m – 450 km');let targets=[];for(let m=0;m<=length;m+=5000)targets.push(m);if(length-targets.at(-1)>1)targets.push(length);let i=0,start=0;return {length,sites:targets.map(m=>{while(i<segments.length-1&&start+segments[i]<m){start+=segments[i++]}let [lat,lon]=interpolate(path[i],path[i+1],segments[i]?(m-start)/segments[i]:0);return {id:crypto.randomUUID(),pk:pk(origin+m),name:'',kind:'route',lat,lon}})}}
export function validate(s){if(s.weatherSource!==undefined&&!['openmeteo','google','combined'].includes(s.weatherSource))throw Error('Invalid weather source');let nums=['rainYellow','rainRed','probYellow','probRed','wet24','asphalt','concrete','wind','cape'];if(!nums.every(k=>valid(s[k]))||s.rainYellow<=0||s.rainRed<s.rainYellow||s.probYellow<0||s.probRed>100||s.probRed<s.probYellow||s.wet24<=0||s.wind<=0||s.cape<=0||s.asphalt< -40||s.asphalt>60||s.concrete<0||s.concrete>60)throw Error('Invalid thresholds / 阈值无效');if(!['zh','fr','en'].includes(s.lang)||!validZone(s.zone)||!/^google_weathernext[a-z0-9_]+$/.test(s.model))throw Error('Invalid settings');if(!Array.isArray(s.route)||!s.route.every(geo))throw Error('Invalid route');if(s.sites.length>100||new Set(s.sites.map(x=>x.pk)).size!==s.sites.length)throw Error('1–100 distinct PK / 桩号不能重复');for(let p of s.sites)if(!/^[a-zA-Z0-9-]{1,64}$/.test(p.id)||!['route','bridge','culvert','low','depot','plant'].includes(p.kind||'route')||!p.pk||!geo([p.lat,p.lon])||p.rainRed!=null&&(!valid(p.rainRed)||p.rainRed<s.rainYellow)||p.wet24!=null&&(!valid(p.wet24)||p.wet24<=0))throw Error('Invalid point / 监测点无效');}
export function checkData(d){let h=d.hourly,u=d.hourly_units;if(!h?.time?.length||!Object.values(h).every(a=>a.length===h.time.length)||!h.time.every((t,i)=>valid(t)&&(!i||t-h.time[i-1]===3600)))throw Error('Invalid hourly data');for(let [k,v]of [['precipitation','mm'],['temperature_2m','°C'],['wind_speed_10m','m/s']])if(u[k]!==v)throw Error('Invalid units');return d}
const cols=(d,k)=>Object.keys(d?.hourly||{}).filter(x=>x===k||new RegExp('^'+k+'_member[0-9]+$').test(x));
export function hours(f,now=Date.now(),count=192){let indices={};for(let k of ['a','g','s','i','d'])indices[k]=new Map((f[k]?.hourly.time||[]).map((t,i)=>[t,i]));const v=(k,c,t)=>{let x=f[k]?.hourly[c]?.[indices[k].get(t)];return valid(x)?x:null},gv=(c,t)=>cols(f.g,c).map(k=>v('g',k,t)).filter(valid);let start=(Math.floor(now/3600000)+1)*3600;return Array.from({length:count},(_,i)=>{let t=start+i*3600,r=gv('precipitation',t),temps=gv('temperature_2m',t),previous=Array.from({length:24},(_,j)=>v('s','precipitation',t-(j+1)*3600));return {t,comparisonRequired:true,ifs:v('i','precipitation',t),icon:v('d','precipitation',t),it:v('i','temperature_2m',t),dt:v('d','temperature_2m',t),iw:v('i','wind_speed_10m',t),dw:v('d','wind_speed_10m',t),a:v('a','precipitation',t),p50:q(r,.5),p90:q(r,.9),prob:r.length?100*r.filter(x=>x>.2).length/r.length:null,n:r.length,expected:cols(f.g,'precipitation').length,at:v('a','temperature_2m',t),gt:temps.length?temps.reduce((a,b)=>a+b,0)/temps.length:null,wind:max([v('a','wind_speed_10m',t),q(gv('wind_speed_10m',t),.9),v('s','wind_speed_10m',t),v('i','wind_speed_10m',t),v('d','wind_speed_10m',t)]),gust:max(['s','i','d'].map(k=>v(k,'wind_gusts_10m',t))),cape:max(['s','i','d'].map(k=>v(k,'cape',t))),code:['s','i','d'].map(k=>v(k,'weather_code',t)).find(c=>c>=95&&c<=99)??v('s','weather_code',t),wet:previous.every(valid)?previous.reduce((a,b)=>a+b,0):null}})}
export function assess(h,s,p,activity,stale=false){let level=0,reasons=[],missing=false,add=(l,k)=>{level=Math.max(level,l);reasons.push(k)};if(h.code>=95&&h.code<=99)add(2,'thunder');if(['lifting','emulsion'].includes(activity)){if(max([h.wind,h.gust])>s.wind)add(2,'wind');missing=!valid(h.wind)||!valid(h.gust)||!valid(h.code)}else{if(max([h.a,h.ifs,h.icon,h.p90])>=(p.rainRed??s.rainRed)||h.prob>s.probRed)add(2,'rainRed');else if(max([h.a,h.ifs,h.icon,h.p90])>=s.rainYellow||h.prob>=s.probYellow)add(1,'rainYellow');missing=!valid(h.a)||!valid(h.p90)||h.n<2||h.n<h.expected||!valid(h.code)}if(h.comparisonRequired)missing||=!valid(h.ifs)||!valid(h.icon)||!valid(h.it)||!valid(h.dt)||!valid(h.iw)||!valid(h.dw);if(h.cape>=s.cape)add(1,'cape');if(['earth','asphalt'].includes(activity)){if(h.wet>=(p.wet24??s.wet24))add(1,'wet');missing||=!valid(h.wet)}if(activity==='asphalt'){if(valid(h.at)&&h.at<s.asphalt||valid(h.gt)&&h.gt<s.asphalt||valid(h.it)&&h.it<s.asphalt||valid(h.dt)&&h.dt<s.asphalt)add(2,'cold');missing||=!valid(h.at)||!valid(h.gt)}if(activity==='concrete'){if(max([h.at,h.gt,h.it,h.dt])>s.concrete)add(1,'hot');missing||=!valid(h.at)||!valid(h.gt)}if(stale){missing=true;reasons.push('stale')}if(missing){if(level!==2)level=-1;reasons.push('missing')}return {level,reasons:reasons.length?reasons:['ok']}}
export function totals(f,rows){let index=new Map((f.g?.hourly.time||[]).map((t,i)=>[t,i])),sums=cols(f.g,'precipitation').map(k=>rows.map(h=>f.g.hourly[k][index.get(h.t)])).filter(a=>a.length&&a.every(valid)).map(a=>a.reduce((x,y)=>x+y,0));return {ifs:rows.length&&rows.every(h=>valid(h.ifs))?rows.reduce((a,h)=>a+h.ifs,0):null,icon:rows.length&&rows.every(h=>valid(h.icon))?rows.reduce((a,h)=>a+h.icon,0):null,a:rows.length&&rows.every(h=>valid(h.a))?rows.reduce((a,h)=>a+h.a,0):null,p50:q(sums,.5),p90:q(sums,.9),n:sums.length}}
export async function getJSON(url,signal){let r=await fetch(url,{signal:signal||AbortSignal.timeout(45000)});if(!r.ok)throw Error(`HTTP ${r.status}`);return r.json()}
export async function forecast(p,s,key){let queries=[['a','https://api.open-meteo.com/v1/forecast','ecmwf_aifs025_single'],['g','https://ensemble-api.open-meteo.com/v1/ensemble',s.model],['s','https://api.open-meteo.com/v1/forecast','gfs_global'],['i','https://api.open-meteo.com/v1/forecast','ecmwf_ifs'],['d','https://api.open-meteo.com/v1/forecast','icon_global']];let f={id:p.id,fetched:Date.now(),modelSetVersion:2,errors:[]};for(let [k,base,model] of queries){try{if(s.commercial){if(!key)throw Error('API key required');base=base.replace('https://','https://customer-')}let u=new URL(base);u.search=new URLSearchParams({latitude:p.lat,longitude:p.lon,models:model,hourly:'temperature_2m,precipitation,wind_speed_10m'+(['s','i','d'].includes(k)?',wind_gusts_10m,weather_code,cape':''),wind_speed_unit:'ms',timeformat:'unixtime',timezone:'GMT',forecast_days:'8',past_days:'1',...(s.commercial?{apikey:key}:{})});f[k]=checkData(await getJSON(u))}catch(e){f[k]=null;f.errors.push(`${model}: ${e.name==='TimeoutError'?'timeout':e.message}`)}await new Promise(r=>setTimeout(r,200))}return f}
export function parseCSV(text){let rows=[],row=[],v='',quote=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){v+='"';i++}else quote=!quote}else if(!quote&&(c===','||c==='\n'||c==='\r')){row.push(v);v='';if(c!==','){if(row.some(x=>x.length))rows.push(row);row=[];if(c==='\r'&&text[i+1]==='\n')i++}}else v+=c}if(quote)throw Error('CSV quotes');if(v||row.length){row.push(v);rows.push(row)}return rows}
export const cell=x=>{x=String(x??'');if(/^[=+@-]/.test(x)&&!Number.isFinite(Number(x)))x="'"+x;return '"'+x.replaceAll('"','""')+'"'};
export function review(text,history,s,now=Date.now()){let [header,...rows]=parseCSV(text);if(header?.join(',')!=='chainage,hour_end,rain_mm')throw Error('CSV: chainage,hour_end,rain_mm');let seen=new Set(),result=[];for(let row of rows){if(row.length!==3)throw Error('CSV columns');let [pk,when,rain]=row;if(!rain.trim())throw Error('YYYY-MM-DD HH:00');let t=(/(?:Z|[+-]\d{2}:\d{2})$/.test(when)?Date.parse(when):localToEpoch(when,s.zone))/1000,n=Number(rain),p=s.sites.find(x=>x.pk===pk);if(!valid(t)||!valid(n)||n<0||!p)throw Error('Invalid observation / 实测无效');if(t*1000<now-7*86400000||t*1000>now)continue;let id=pk+when;if(seen.has(id))throw Error('Duplicate / 重复');seen.add(id);let candidates=history.flatMap(b=>b.rows.filter(h=>h.id===p.id&&h.t===t&&valid(h.p50)).map(h=>({...h,lead:(t*1000-b.fetched)/3600000}))).filter(h=>h.lead>=6&&h.lead<=30).sort((a,b)=>Math.abs(a.lead-24)-Math.abs(b.lead-24));if(candidates.length)result.push({pk,t,actual:n,p50:candidates[0].p50,error:candidates[0].p50-n})}return result}

export function rainSpread(h){let values=[h.a,h.ifs,h.icon,h.p50].filter(valid);return values.length<2?null:Math.max(...values)-Math.min(...values)}
